  ui_story_31530401_68_dialog_content = "¡Instructor! ¡Todos queremos entrenamiento extra!",
  ui_story_31530401_69_dialog_content = "(Los nuevos reclutas que se quejaban ahora están muy animados, como si fueran personas completamente diferentes...)",
