  ui_story_31530401_73_dialog_content = "PlayerName, casi es el amanecer. Es hora de dirigirnos a nuestra próxima parada.",
  ui_story_31530401_74_dialog_content = "<color=#e8d9bb>Ciudad de Gannon, Centro de Investigación</color>",
  ui_story_31530401_75_dialog_content = "Esos son los resultados de nuestra investigación en los últimos días. Naturalmente, continuaremos iterando sobre nuestros proyectos en el futuro.",
