  ui_story_31530401_86_dialog_content = "¿En serio? Ja... Ja...",
  ui_story_31530401_87_dialog_content = "Y estas engañosamente hermosas variantes de rosas que Jola está cultivando...",
  ui_story_31530401_88_dialog_content = "Sus espinas son en realidad cien veces más afiladas que las rosas ordinarias.",
  ui_story_31530401_89_dialog_content = "Si pudieran ser plantados en la línea de frente, efectivamente reducirían la velocidad de los Eclipsites que se acercan.",
  ui_story_31530401_90_dialog_content = "(¿Por qué no pensé en eso?)",
  ui_story_31530401_91_dialog_content = "(Aunque sería un destino cruel para estas hermosas flores...)",
  ui_story_31530401_92_dialog_content = "(¡Pero esto significa que finalmente tengo un plan de investigación factible para presentar!)",
  ui_story_31530401_93_dialog_content = "Solo soy un soldado.",
  ui_story_31530401_94_dialog_content = "Estoy profundamente conmovido por la innovación y creatividad de tu investigación.",
