  ui_story_31530401_103_dialog_content = "¿Eh? Ah... Y-Yo también... También voy a... realizar algunos experimentos...",
  ui_story_31530401_104_dialog_content = "(Todos parecían deprimidos por los resultados de su investigación, pero ahora hay un renovado espíritu de lucha en sus ojos...)",
