  ui_story_31530401_115_dialog_content = "¿Todo esto realmente sucede en un día...?",
  ui_story_31530401_116_dialog_content = "¡Compañeros Illuminans! La guerra es cruel, y el miedo ante la batalla es solo nuestra reacción instintiva.",
