  ui_story_31530401_142_dialog_content = "¿PlayerName?",
  ui_story_31530401_143_dialog_content = "Deja de alejarte y ven a la reunión.",
  ui_story_31530401_144_dialog_content = "¿Reunión? ¿Tengo que ir también? ¿Q-Quién más va a asistir?",
