  ui_story_31530401_153_dialog_content = "Uno a la vez...",
  ui_story_31530401_154_dialog_content = "<color=#828282>¡Bam!</color>",
  ui_story_31530401_155_dialog_content = "*Ronquido*",
  ui_story_31530401_156_dialog_content = "(Eso fue aterrador. Solo fue un sueño...)",
  ui_story_31530401_157_dialog_content = "Finalmente estás despierto.",
  ui_story_31530401_158_dialog_content = "(¿Eh? ¿La reunión de Reinhardt ya terminó?)",
