  ui_story_31530401_167_dialog_content = "Bien...",
  ui_story_31530401_168_dialog_content = "(¿Por qué está tan callada? Debe seguir estando enfadada.)",
  ui_story_31530401_169_dialog_content = "(La atmósfera es tan incómoda...)",
  ui_story_31530401_170_dialog_content = "Um... ¡Lo siento mucho!",
  ui_story_31530401_171_dialog_content = "¿Eh? ¿Por qué dices lo siento?",
  ui_story_31530401_172_dialog_content = "Estaba demasiado cansado antes... así que no terminé de escribir el resumen de hoy...",
  ui_story_31530401_173_dialog_content = "Por favor, no te enfades... ¡Encontraré tiempo para terminarlo!",
  ui_story_31530401_174_dialog_content = "¿Yo? ¿Enojado?",
  ui_story_31530401_175_dialog_content = "Jajajaja, lo siento, lo siento! No puedo evitar fruncir el ceño cuando tengo hambre.",
  ui_story_31530401_176_dialog_content = "Vivian me ha estado regañando sobre esto durante mucho tiempo, pero no he dejado el hábito.",
  ui_story_31530401_177_dialog_content = "¡Oh! Ya veo.",
  ui_story_31530401_178_option_content = "Eso es un alivio.",
  ui_story_31530401_179_dialog_content = "¿Mmm? ¿Estás feliz de que no me haya deshecho de este mal hábito mío?",
  ui_story_31530401_180_dialog_content = "Eso es... ¡Lo siento, no! ¡Eso no es lo que quise decir!",
  ui_story_31530401_181_dialog_content = "Pero no creo que sea realmente un mal hábito.",
  ui_story_31530401_182_option_content = "Qué hábito tan interesante.",
  ui_story_31530401_183_dialog_content = "Se siente como si la siempre perfecta Gran Mariscal pareciera un poco más cercana a nosotros, la gente normal, ahora.",
  ui_story_31530401_184_dialog_content = "¿Siempre perfecto? No diría eso de mí mismo.",
  ui_story_31530401_185_dialog_content = "¿Cómo no lo eres? ¡Hiciste en un día hoy tanto como yo hago en un mes!",
  ui_story_31530401_186_dialog_content = "Y cada tarea se manejó a la perfección, sin fallas.",
  ui_story_31530401_187_dialog_content = "No es de extrañar que la gente de Illumina idolatre tanto al Gran Mariscal.",
  ui_story_31530401_188_dialog_content = "Lo vi con mis propios ojos hoy. ¡Debes conocer algún tipo de magia para manipular las mentes de las personas!",
  ui_story_31530401_189_dialog_content = "¡Jajajaja, PlayerName, tienes bastante imaginación!",
  ui_story_31530401_190_dialog_content = "El trabajo de un nuevo recluta es entrenar, el trabajo de un investigador es experimentar...",
  ui_story_31530401_191_dialog_content = "Y el trabajo del Gran Mariscal es trazar la estrategia a seguir cuando la gente pierde su camino.",
  ui_story_31530401_192_dialog_content = "Si insistes en decir que tengo algún tipo de habilidad mágica, solo puedo decir—",
  ui_story_31530401_193_dialog_content = "¡Eso nos hace dos!",
  ui_story_31530401_194_dialog_content = "¿Ah?",
  ui_story_31530401_195_dialog_content = "La última Caelestita legendaria carece de fuerza física y, por falta de una palabra mejor, es frágil.",
  ui_story_31530401_196_dialog_content = "Aún así, eres capaz de conseguir que tantas personas se unan a ti en tus aventuras.",
  ui_story_31530401_197_dialog_content = "Incluso el subordinado de Vivian, Vice, está dispuesto a seguirte en tus andanzas por el mundo.",
  ui_story_31530401_198_dialog_content = "¿También usas magia para atraer a las personas hacia ti?",
  ui_story_31530401_199_dialog_content = "Eso es...",
  ui_story_31530401_200_dialog_content = "<color=#e8d9bb>*gruñido de estómago*</color>",
  ui_story_31530401_201_dialog_content = "¡Jajaja! Parece que tu estómago también ha empezado a protestar, ¿eh?",
  ui_story_31530401_202_dialog_content = "Vamos, satisfagámoslos primero.",
  ui_story_31530401_203_dialog_content = "¡Entonces volveremos y terminaremos el resto del papeleo, y continuaremos esta conversación después!",
  ui_story_31530401_204_dialog_content = "(¿Vamos a seguir trabajando?!)",
  ui_story_31530401_205_dialog_content = "(¿Cuándo terminará este día...)",
  ui_story_31530401_206_dialog_content = "((Reinhardt no es una Gran Mariscal, estoy bastante seguro de que es algún tipo de criatura inagotable.)",
  ui_story_31530401_207_dialog_content = "¡Woo-hoo!",
  ui_story_31530401_208_dialog_content = "¡Delicioso! El asado de carne es el mejor!",
  ui_story_31530401_209_dialog_content = "¡Otra ración, por favor!",
  ui_story_31530601_1_dialog_content = "¿Es ese hombre joven el legendario Caelestite?",
  ui_story_31530601_2_dialog_content = "De ninguna manera, parece demasiado desaliñado para ser algún tipo de leyenda.",
  ui_story_31530601_3_dialog_content = "Todos tienen sus propios gustos. ¿Quizás él simplemente prefiere verse así?",
  ui_story_31530601_4_dialog_content = "Pero como el único superviviente de toda una raza, debe haber heredado algún tipo de fortuna, ¿verdad? Incluso es dueño de todo Eraveil—",
  ui_story_31530601_5_dialog_content = "(Han estado mirándome todo este tiempo... Y ahora están empezando a decir cosas realmente locas.)",
  ui_story_31530601_6_dialog_content = "(¿Es este realmente el lugar correcto? ¿Por qué me invitaría a un banquete tan elegante...?)",
  ui_story_31530601_7_dialog_content = "\"Querido(a) PlayerName,\"",
  ui_story_31530601_8_dialog_content = "\"Si tienes tiempo, ¿podrías venir a Umbraton? La dirección es #XXX en la calle XXXX. P.D. Incluso si no tienes tiempo, por favor, haz lo posible por asistir.\"",
  ui_story_31530601_9_dialog_content = "Perdóname, pero ¿eres el representante de Eraveil?",
  ui_story_31530601_10_dialog_content = "¡¿Eh?!",
  ui_story_31530601_11_dialog_content = "Te conozco. Eres el último Caelestita, heredando el poder más malvado de tu raza.",
  ui_story_31530601_12_dialog_content = "¡Controlas las mentes de cualquier criatura viviente en Astra! ¡Con un solo capricho, puedes convertir a todos en esta sala en tu títere!",
  ui_story_31530601_13_dialog_content = "¡Ahora solo espera un segundo!",
  ui_story_31530601_14_dialog_content = "¿Convertirnos en marionetas, dices? Lo siento, pero la riqueza y el estatus ya son más que capaces de lograr eso. No hagas caso a estas personas, amigo mío; descubrirás que algunos nobles son superiores al resto.",
  ui_story_31530601_15_dialog_content = "Nadie quiere hacer amigos con la suciedad, pero puedo ayudarte en ese aspecto.",
  ui_story_31530601_16_dialog_content = "P-Puedo cuidarme solo, gracias...",
  ui_story_31530601_17_dialog_content = "¿Qué? ¿La Caelestita? ¿Dónde?! Déjame ver, déjame ver—",
  ui_story_31530601_18_dialog_content = "—Damas y caballeros.",
  ui_story_31530601_19_dialog_content = "(¡Esa voz...!)",
  ui_story_31530601_20_dialog_content = "Acercarse a él es perfectamente aceptable, pero les pido que se comporten con un poco más de dignidad.",
  ui_story_31530601_21_dialog_content = "Si no hay otra razón, al menos hazlo por mí. Después de todo—",
  ui_story_31530601_22_dialog_content = "PlayerName está aquí a mi petición.",
  ui_story_31530601_23_dialog_content = "Reinhardt...! ¡Realmente estás aquí!",
  ui_story_31530601_24_dialog_content = "(Y en un atuendo tan formal también...)",
  ui_story_31530601_25_dialog_content = "¡El Gran Mariscal de Illumina! Ella invitó al Caelestite...",
  ui_story_31530601_26_dialog_content = "Y la Caelestita la llamó por su nombre...",
  ui_story_31530601_27_dialog_content = "Sr. PlayerName, ¡debes venir al próximo baile de nuestra familia!",
  ui_story_31530601_28_dialog_content = "¡Nos sentiríamos honrados de tenerte como nuestro invitado!",
  ui_story_31530601_29_dialog_content = "Por aquí, PlayerName.",
  ui_story_31530601_30_dialog_content = "(... ¡Estoy salvado!)",
  ui_story_31530601_31_dialog_content = "<color=#e8d9bb>La multitud se separó instintivamente, y todos los ojos estaban pegados a cada paso que daban al subir las escaleras.</color>",
  ui_story_31530601_32_dialog_content = "...Lo siento por eso. Estaba en medio de una reunión importante y no pude escapar a tiempo para salvarte de esas personas.",
  ui_story_31530601_33_dialog_content = "¡No te preocupes por eso! Si no fuera por eso, nunca habría sabido lo ridículos que se han vuelto los rumores sobre mí.",
  ui_story_31530601_34_dialog_content = "Aparentemente, soy un villano rico capaz de esclavizar todas las mentes en Astra... Después de hoy, no me sorprendería si empezaran a acusar a Illumina de estar en connivencia con Eraveil!",
  ui_story_31530601_35_dialog_content = "¡Jajaja, entonces parece que me preocupaba por nada! Bueno, me gusta ver este lado <color=#FFB400>libre y rebelde</color> de ti.",
  ui_story_31530601_36_dialog_content = "No estoy seguro si eso fue un cumplido o no...",
  ui_story_31530601_37_dialog_content = "Estás muy diferente a lo habitual hoy. Me está costando mucho entenderte ahora.",
  ui_story_31530601_38_dialog_content = "¿Diferente? ¿Estás diciendo que soy más genial de lo habitual?",
  ui_story_31530601_39_dialog_content = "¡Justo iba a decir eso! Pero... sí, tu genialidad y tu presencia se sienten muy diferentes, algo así como—",
  ui_story_31530601_40_dialog_content = "Estás a punto de decir algo duro, \"¡No está mal, ahora comienza a hacer estas armas!\" o \"Quiero su perfil en mi escritorio en diez minutos.\"",
  ui_story_31530601_41_dialog_content = "... ¡No creo que el Gran Mariscal de Illumina deba parecer así para nadie!",
  ui_story_31530601_42_dialog_content = "Pero así es como me sentí cuando me rescataste de la multitud... ¡Fue genial!",
  ui_story_31530601_43_dialog_content = "Esas personas no son nada como tú. Todo lo que les importa son sus propios intereses... Pero está bien, ya que el mundo aún necesita personas como ellas.",
  ui_story_31530601_44_dialog_content = "Los manejaré yo, así que por favor vive libremente y al contenido de tu corazón.",
  ui_story_31530601_45_dialog_content = "Eso es algo que solo tú puedes hacer.",
  ui_story_31530601_46_dialog_content = "¿Solo yo...?",
  ui_story_31530601_47_dialog_content = "Me sorprendió saber que Reinhardt había invitado a un invitado esta noche, pero considerando que es PlayerName, lo entiendo completamente.",
  ui_story_31530601_48_dialog_content = "¡Señor Sombrío...!",
  ui_story_31530601_49_dialog_content = "(Entonces, ¿la reunión importante fue entre él y Reinhardt?)",
  ui_story_31530601_50_dialog_content = "Ser el Señor de las Sombras debe ser agotador a veces. Los soldados de Illumina suelen ser rectos y simples, lo que hace que tratar con ellos sea bastante sencillo. Tú, por otro lado, tienes que lidiar con esas personas de abajo.",
  ui_story_31530601_51_dialog_content = "En mi opinión, inspirar y liderar a las masas rectas y sencillas es un trabajo mucho más desalentador.",
  ui_story_31530601_52_dialog_content = "Las negociaciones de hoy habrían sido imposibles sin tu presencia.",
  ui_story_31530601_53_dialog_content = "Solo puedo hacer un tercio del trabajo, así que daré lo mejor de mí.",
  ui_story_31530601_54_dialog_content = "El resto depende de ti y de la Dama Carleen.",
  ui_story_31530601_55_dialog_content = "(¿¡Carleen también estaba allí?! Me pregunto dónde estará ahora...?)",
  ui_story_31530601_56_dialog_content = "¡Gran Mariscal Reinhardt! Y PlayerName, ¡mi querido amigo!",
  ui_story_31530601_57_dialog_content = "(¿¡Cuándo nos hicimos amigos?!)",
  ui_story_31530601_58_dialog_content = "¿Te gustaría unirte a mis amigos y a mí para una breve charla? Son nobles de Lumopolis, ya ves, y—",
  ui_story_31530601_59_dialog_content = "¿Qué estabas diciendo justo ahora, PlayerName? ¿Que los Eclipsites se habían infiltrado en el Colossus? No te preocupes, ¡te ayudaré a sacarlos!",
  ui_story_31530601_60_dialog_content = "¿Eh?! Ah... ¡E-Eso es correcto! ¡Toneladas de Eclipsites! ¡Vice ha estado defendiéndose de ellos durante tres días! ¡Realmente podríamos usar tu ayuda!",
  ui_story_31530601_61_dialog_content = "Como puede ver, mi buen hombre, nuestro amigo necesita desesperadamente ayuda. Si nos disculpa, debemos irnos.",
  ui_story_31530601_62_dialog_content = "Por favor, ten cuidado. Me aseguraré de notificar a Lady Carleen sobre tu situación.",
  ui_story_31530601_63_dialog_content = "¡Ah, de vuelta en la ciudad de Gannon!",
  ui_story_31530601_64_dialog_content = "Solía pensar que este lugar era tan estrecho y sofocante, pero después de ese banquete, cada bocanada de aire se sentía tan refrescante!",
  ui_story_31530601_65_dialog_content = "...",
  ui_story_31530601_66_dialog_content = "(...¡Vaya! ¡No se suponía que debía decir eso en voz alta!)",
  ui_story_31530601_67_dialog_content = "No te preocupes, no me voy a molestar por lo que dijiste sobre Ciudad Gannon.",
  ui_story_31530601_68_dialog_content = "¡Ella vio a través de mí!",
  ui_story_31530601_69_dialog_content = "Además, para alguien tan libre como tú, este lugar definitivamente se sentiría apretado y sofocante.",
  ui_story_31530601_70_dialog_content = "Nadie... debería acostumbrarse a vivir así.",
  ui_story_31530601_71_dialog_content = "... ¿Puedo preguntar por qué me invitaste a ese banquete en Umbraton hoy? ¿O por qué me pediste que te llevara de vuelta a la Ciudad de Gannon antes de que terminara?",
  ui_story_31530601_72_dialog_content = "N-No estabas planeando usarme como excusa para irte, ¿verdad?",
  ui_story_31530601_73_dialog_content = "Eres mi querido amigo y un aliado confiable. ¿Por qué me burlaría de ti de esa manera?",
  ui_story_31530601_74_dialog_content = "La razón por la que te pedí que vinieras es... ¡Cuidado!",
  ui_story_31530601_75_dialog_content = "(Eso estuvo cerca... ¡Casi me atropella ese vehículo de transporte! Debería prestar más atención a mi entorno...)",
  ui_story_31530601_76_dialog_content = "Cuidado por donde vas. El sector más nuevo de Gannon no necesita ningún sacrificio vivo.",
  ui_story_31530601_77_dialog_content = "¡L-Lo siento! Espera, ¿sector más nuevo? ¿Están ustedes desarrollando una nueva área?",
  ui_story_31530601_78_dialog_content = "Ahora que lo mencionas... ese vehículo de transporte llevaba un montón de plantas, ¿verdad? No creo haber visto nunca una sola planta en la ciudad de Gannon antes.",
  ui_story_31530601_79_dialog_content = "Jeje.",
  ui_story_31530601_80_dialog_content = "... ¿Estoy realmente imaginando cosas?! ¡Esa risa casi sonó como si estuvieras complacido contigo mismo!",
  ui_story_31530601_81_dialog_content = "Lo sabrás una vez que lo veas por ti mismo. ¡Ven conmigo!",
  ui_story_31530601_82_dialog_content = "¿T-Todavía es... Ciudad Gannon?",
  ui_story_31530601_83_dialog_content = "No puedo creerlo...",
  ui_story_31530601_84_dialog_content = "Puedo asegurarte que esto sigue siendo la ciudad de Gannon. Bienvenido a nuestro sector residencial más nuevo.",
  ui_story_31530601_85_dialog_content = "Cuando diseñamos este lugar, queríamos que fuera algo que incluso un Caelestite libre e indisciplinado admiraría.",
  ui_story_31530601_86_dialog_content = "¿Yo? ¿Pero por qué? No es para justificar mis defectos ni nada, pero hay muchas otras personas libres e indisciplinadas en el mundo.",
  ui_story_31530601_87_dialog_content = "No lo veo como una desventaja en absoluto.",
  ui_story_31530601_88_dialog_content = "Estás acostumbrado a vivir en el mundo abierto y disfrutas de un sentido de independencia que te permite ver todo lo que tiene para ofrecer—",
  ui_story_31530601_89_dialog_content = "Eso es lo que significa ser libre y rebelde. No es una desventaja; es una forma rara de felicidad que pocas personas experimentarán.",
  ui_story_31530601_90_dialog_content = "Y esa felicidad es algo que quiero proporcionar a cada persona en Illumina.",
  ui_story_31530601_91_dialog_content = "!!!",
  ui_story_31530601_92_dialog_content = "Durante siglos, la gente de Illumina ha vivido vidas frugales bajo tierra, todo en preparación para una guerra interminable.",
  ui_story_31530601_93_dialog_content = "No tenemos más remedio que vivir así, pero eso no significa que no merezcamos algo mejor.",
  ui_story_31530601_94_dialog_content = "Es por eso que propuse un nuevo plan para mejorar la vida de nuestros ciudadanos. Este nuevo sector es el sitio de prueba para este plan.",
  ui_story_31530601_95_dialog_content = "PlayerName, ¿me ayudarías?",
  ui_story_31530601_96_dialog_content = "Como aliado de Illumina, y la persona más libre del mundo—",
  ui_story_31530601_97_dialog_content = "Por favor, dame una evaluación honesta de nuestro sector más reciente. Tu perspectiva es algo que valoro enormemente.",
  ui_story_31530601_98_dialog_content = "Reinhardt... ¡Estoy asombrado de que hayas ideado algo tan increíble!",
  ui_story_31530601_99_dialog_content = "¡Por supuesto que te ayudaré! P-Pero no estoy exactamente seguro de cómo evaluar este lugar...",
  ui_story_31530601_100_dialog_content = "Es simple. Solo dame tu opinión más sincera sobre ello.",
  ui_story_31530601_101_dialog_content = "¡Espera! Al otro lado de la calle... ¿Es ese un proveedor de automóviles?",
  ui_story_31530601_102_dialog_content = "Escuché que tú y tus amigos descubrieron algo así en una antigua Entrañas. Despertó mi curiosidad, así que hice que Gronru armara un modelo de prueba.",
  ui_story_31530601_103_dialog_content = "¿Bien? ¿Es algo parecido al original?",
  ui_story_31530601_104_dialog_content = "Vamos a averiguarlo. Un bar de desayuno, por favor...",
  ui_story_31530601_105_dialog_content = "¡En realidad salió!",
  ui_story_31530601_106_dialog_content = "¡Esto es increíble! La comida siempre ha sido racionada aquí en Gannon City, pero ahora se puede servir bajo demanda...",
  ui_story_31530601_107_dialog_content = "Es simplemente una cuestión de curso. Ahora que nuestros recursos son lo suficientemente abundantes para sostenernos, la accesibilidad y la comodidad se convierten en nuestras próximas prioridades. Además, a nadie le gusta hacer cola para las cosas.",
  ui_story_31530601_108_dialog_content = "Pasemos a la siguiente calle.",
  ui_story_31530601_109_dialog_content = "¡Qué parque tan hermoso! Nunca había visto algo tan verde en la ciudad de Gannon antes...",
  ui_story_31530601_110_dialog_content = "Migard afirma que todas estas plantas son capaces de crecer bien bajo luz artificial.",
  ui_story_31530601_111_dialog_content = "También tengo dos en mi cuarto. Si alguien como yo puede mantenerlos vivos, ¡entonces el resto de Gannon City no debería tener problemas para hacer lo mismo!",
  ui_story_31530601_112_dialog_content = "¿Y todas estas plataformas de salto y equipos de entrenamiento... Son para hacer ejercicio?",
  ui_story_31530601_113_dialog_content = "Buen ojo. De hecho, estoy orgulloso de llamar a estos algunos de mis mejores trabajos.",
  ui_story_31530601_114_dialog_content = "Incluso alguien que evita el ejercicio podría sentirse tentado a probar estos. ¿No crees?",
  ui_story_31530601_115_dialog_content = "Vamos, deberías probarlo. ¡Te ayudaré!",
  ui_story_31530601_116_dialog_content = "E-Estoy bien, pero... puedo decir que este lugar ha cambiado. Incluso podría describirlo como \"vibrante\" ahora...",
  ui_story_31530601_117_dialog_content = "... ¡Espera, ahora lo entiendo! Fuiste a ese banquete en Umbraton por el bien de este nuevo sector, ¿no es así?",
  ui_story_31530601_118_dialog_content = "¡Correcto! Illumina se ha militarizado demasiado, tanto que ciertas necesidades diarias se han vuelto escasas.",
  ui_story_31530601_119_dialog_content = "Si realmente deseamos expandirnos, necesitaremos el respaldo tanto de Umbraton como de Lumopolis.",
  ui_story_31530601_120_dialog_content = "No quieres que las barras de comida sean lo único en nuestros vendedores automáticos, ¿verdad?",
  ui_story_31530601_121_dialog_content = "Así que por eso te estabas reuniendo con Carleen y Istvan...",
  ui_story_31530601_122_dialog_content = "Una propuesta de negocio que beneficiaría a las tres partes, ese es el acuerdo al que llegamos en aquel entonces.",
  ui_story_31530601_123_dialog_content = "Pero naturalmente, un acuerdo entre tres líderes no será suficiente. Nobles, gremios, pandillas... Lo más importante es tener a todos ellos a bordo también.",
  ui_story_31530601_124_dialog_content = "¿Es por eso que todas esas personas ricas e importantes también estaban allí?",
  ui_story_31530601_125_dialog_content = "Por supuesto. Después de todo, ¿cuál de ellos podría permitirse perder una oportunidad de negocio como esta? Para ser honesto, no soy muy bueno tratando con ellos, igual que tú.",
  ui_story_31530601_126_dialog_content = "Pero definitivamente algún día lo dominaré. Incluso los comerciantes más astutos no son nada comparados con las personas mayores tercas con las que tengo que trabajar todos los días.",
  ui_story_31530601_127_dialog_content = "Decidida, capaz y diplomática... Esa es la Gran Mariscal de Illumina.",
  ui_story_31530601_128_dialog_content = "Pero eso es mucho para manejar todo por ti mismo... ¿No te sentirás agotado?",
  ui_story_31530601_129_dialog_content = "Difícilmente lo creo. Después de todo, no soy yo quien conduce los vehículos de transporte o cuida las plantas.",
  ui_story_31530601_130_dialog_content = "Eso no significa que tu plato no esté lleno. Mencionaste Gronru y Migard, así como este lugar que tiene \"algunos de tus mejores trabajos\"...",
  ui_story_31530601_131_dialog_content = "No tiene sentido negarlo. ¡Tienes tus manos en casi todos los aspectos del desarrollo del nuevo sector!",
  ui_story_31530601_132_dialog_content = "E-Ejem... Es importante monitorear cada paso de un proceso como este... Además, no estoy buscando cumplidos personales aquí.",
  ui_story_31530601_133_dialog_content = "Estoy pidiendo tu sincera opinión sobre este lugar.",
  ui_story_31530601_134_dialog_content = "No me mires como al Gran Mariscal, sino como a otro amigo y camarada en armas, y dime exactamente cómo te sientes al respecto. ¡Incluso las críticas duras están totalmente bien!",
  ui_story_31530601_135_option_content = "Realmente creo que el nuevo sector es increíble.",
  ui_story_31530601_136_dialog_content = "Es tan tranquilo y pacífico. Incluso alguien tan serio como tú se siente lo suficientemente relajado para charlar tanto conmigo aquí. ¿No es ese el punto?",
  ui_story_31530601_137_dialog_content = "¿Crees... que me siento relajado?",
  ui_story_31530601_138_option_content = "Creo que esperas demasiado de ti mismo.",
  ui_story_31530601_139_dialog_content = "Después de escucharte hablar sobre el nuevo sector, puedo decir que has dado mucho a este lugar. Suena tan feliz y orgulloso, como si estuvieras presentando algo que amas mucho.",
  ui_story_31530601_140_dialog_content = "¿Sueno... feliz?",
  ui_story_31530601_141_dialog_content = "¿Quieres decir que no te diste cuenta?",
  ui_story_31530601_142_dialog_content = "Mencionaste tantas cosas sobre ti mismo hace un momento. Cómo odias hacer cola, o cómo no puedes cuidar de las plantas... Y lo orgulloso que te sientes cuando las cosas se hacen.",
  ui_story_31530601_143_dialog_content = "Jaja... ¡Jajajajaja!",
  ui_story_31530601_144_dialog_content = "¡Sabía que invitarte aquí era la elección correcta!",
  ui_story_31530601_145_dialog_content = "Ah... No recuerdo la última vez que me reí mucho así.",
  ui_story_31530601_146_dialog_content = "Creo que fue cuando todavía estaban aquí...",
  ui_story_31530601_147_dialog_content = "¿Ellos? ¿Te refieres a...",
  ui_story_31530601_148_dialog_content = "Mi hermana, así como Helios.",
  ui_story_31530601_149_dialog_content = "Solíamos hacer todo juntos. Estudiar, entrenar y vivir nuestras vidas.",
  ui_story_31530601_150_dialog_content = "En nuestro tiempo libre, también veníamos a lugares como este y mirábamos a Gannon City desde lo alto. Hablábamos de todo tipo de cosas sin sentido, riendo mientras disfrutábamos de la brisa.",
  ui_story_31530601_151_dialog_content = "Recordar ese tiempo me hace sentir tan nostálgico.",
  ui_story_31530601_152_dialog_content = "Reinhardt...",
  ui_story_31530601_153_dialog_content = "Pero no te preocupes. Nada puede permanecer igual para siempre, y aunque algunos cambios pueden realmente agobiarnos—",
  ui_story_31530601_154_dialog_content = "A menudo, el cambio es emocionante.",
  ui_story_31530601_155_dialog_content = "Solo mira la ciudad de Gannon: está cambiando de un lugar apretado y sofocante a una ciudad vibrante y abierta, ¿no es así?",
  ui_story_31530601_156_dialog_content = "Y según tu imaginación, incluso yo parezco más relajado y hablador ahora.",
  ui_story_31530601_157_dialog_content = "¡No me estaba imaginando nada!",
  ui_story_31530601_158_dialog_content = "Jeje. Usted mismo es una persona bastante increíble.",
  ui_story_31530601_159_dialog_content = "Después de todos estos años, me ayudaste a recordar lo que se siente al charlar y reír con mis amigos... Y eso es más que suficiente para mí.",
  ui_story_31530601_160_dialog_content = "... ¿Reinhardt?",
  ui_story_31530601_161_dialog_content = "Pero Denier y Helios ya no están conmigo... Y después de hoy, volverás a volar por todo el mundo de nuevo.",
  ui_story_31530601_162_dialog_content = "Y yo estaré aquí, vigilando toda la ciudad de Gannon.",
  ui_story_31530601_163_dialog_content = "Seré testigo del surgimiento de este nuevo sector, un espacio verde y vibrante para que todos disfruten.",
  ui_story_31530601_164_dialog_content = "Es un lugar donde nuestra gente puede vivir sin restricciones y elegir las cosas que quieren comer.",
  ui_story_31530601_165_dialog_content = "Para los ciudadanos de Illumina, el entrenamiento no es solo nuestro deber; también es un pasatiempo y una forma de mantenernos saludables.",
  ui_story_31530601_166_dialog_content = "Aquí, los niños pueden subir a los lugares más altos y pasar un tiempo precioso con sus amigos, riendo y mirando la ciudad como lo hicimos una vez. Ninguna guerra o conflicto los alcanzará aquí.",
  ui_story_31530601_167_dialog_content = "Como Gran Mariscal de la Federación Illumina... prometo vigilar todo.",
  ui_story_31530601_168_dialog_content = "Siempre estaré aquí.",
  ui_story_31530601_169_dialog_content = "(La Iluminación Iluminada... Ahora lo veo.)",
  ui_story_31530601_170_dialog_content = "(Es imposible ver a esta persona como simplemente otra buena amiga. Ella es mucho más que eso.)",
  ui_story_31530601_171_dialog_content = "Ahora bien, mi amigo <color=#FFB400>libre e indomable</color>... Dado que tienes una opinión tan alta de este lugar, ¿quizás podríamos intercambiar un terreno en Eraveil por un barrio aquí? ¿Qué te parece?",
  ui_story_31530601_172_dialog_content = "¡Puedo ayudarte a alistarte en nuestro ejército e incluso comenzar como teniente!",
  ui_story_31530601_173_dialog_content = "... ¿Quieres que te dé mi casa a cambio de trabajar bajo tus órdenes? ¿Qué pasó con no burlarse de tus amigos?!",
  ui_story_31530601_174_dialog_content = "¡Jajajaja!"
}
return config
